      if (Pet mode request is received and front MCU initialization is 0?) then (yes)
        :Remain in state 186;
        if (Fast charging is inactive?) then (yes)
          :Switch to state 12;
        endif
      endif
      :After pet mode ends;
      :Shut down;
      :Exit;
      stop
    case (Fifth)
      if (Battery SOC is 20 and front MCU initialization is 0?) then (yes)
        :Stay in state 186;
        if (Fast charging is disabled?) then (yes)
          :Switch to state 12;
        endif
      endif
      if (SOC reaches 80 and DCDC state is 3?) then (yes)
        :Shut down;
        :Exit;
        stop
      endif
    endswitch
  endif
endif
